// Authoring only: reconstructs candidates from local extractions, never approvals/publication.
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
const out = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(out, '../../..');
const inventory = JSON.parse(fs.readFileSync(path.join(root, 'data/extracted/inventory.json'), 'utf8'));
const documents = new Map(inventory.map(entry => [entry.articleId, JSON.parse(fs.readFileSync(path.join(root, 'data/extracted', entry.outputFile), 'utf8'))]));
const primary = 'article-48bdcebcffc6';
const ids = { sbd: 'article-d4b0c4f9d75f', art: 'article-94e7a19d8878', chip: 'article-eca18e5843e2', agenda: 'article-d0d500126a80', op: 'article-39adb0cfa84e', hci: 'article-e13c3cb65c28' };
const cards = [];
function source(id, pages, sections = []) {
  const document = documents.get(id);
  return { file: document.file, title: document.title, pages, sections, evidence: pages.map(page => document.pages.find(item => item.page === page).text) };
}
function add(question, answer, pages, sections, related = []) {
  const suffix = String(cards.length + 9).padStart(2, '0');
  cards.push({ id: `${primary}-${suffix}`, articleId: primary, question, answer, source: source(primary, pages, sections), kind: related.length ? 'synthesis' : 'direct', ...(related.length ? { relatedSources: related.map(([id, pages, sections]) => ({ articleId: ids[id], source: source(ids[id], pages, sections) })) } : {}) });
}
const intro = ['1 Introduction'];
const adaptation = ['2.1 Adaptations from the Original Protocol to Our Context'];
const corpus = ['2.2 Corpus Generation and Recording of Usage'];
const classification = ['2.3 DPs Classification'];
const results = ['3 Results'];
const discussion = ['4 Discussions'];

add('Na definição adotada pelo Interact, por que a análise de um padrão enganoso precisa considerar a decisão induzida e o interesse do usuário, além da aparência da interface?',
'O artigo apresenta DPs como [[escolhas de design de interface que conduzem a decisões que o usuário talvez não tomasse]], frequentemente em benefício do serviço. Menciona comportamentos contrários ao interesse do usuário, como compras impulsivas e instalação de aplicativos desnecessários. Portanto, o objeto de análise não é apenas uma tela visualmente carregada: é a configuração da interação e da decisão que ela favorece. Essa é a fundamentação conceitual adotada pelo trabalho, não uma demonstração causal de que cada ocorrência observada produziu esses comportamentos nos participantes; o estudo classifica interfaces, sem medir individualmente tais consequências.', [1], intro);

add('Por que o Interact considera insuficiente tratar taxonomias construídas em contextos WEIRD como descrição exaustiva das manifestações de padrões no Sul Global?',
'A introdução observa que grande parte dos estudos ocorreu em sociedades [[ocidentais e anglocêntricas]], enquanto diferenças entre países podem alterar reconhecimento e experiência dos padrões. O exemplo japonês de Linguistic Dead Ends mostra que uma investigação em outro contexto pode revelar formas de manipulação linguística pouco visíveis no repertório anterior. A consequência metodológica é [[examinar a adequação contextual das categorias]], em vez de pressupor cobertura universal. O artigo não descarta as taxonomias anteriores: combina-as com achados posteriores para produzir uma base comparável, reconhecendo que essa base pode não capturar integralmente particularidades do Sul Global.', [1, 2], intro);

add('Como a discussão sobre o enquadramento WEIRD ou não WEIRD do Brasil exige cuidado para não transformar contexto nacional em uma explicação homogênea?',
'O texto afirma que determinar se o contexto brasileiro é WEIRD ou não WEIRD é [[difícil devido à complexidade dos indicadores sociais]]. Destaca desigualdade educacional, falta de letramento digital e distribuição desigual de tecnologias da informação e comunicação. Esses aspectos justificam a hipótese de particularidades na manifestação dos DPs e a investigação de um grande mercado digital do Sul Global. Não autorizam afirmar que todos os brasileiros apresentam a mesma vulnerabilidade ou que uma nacionalidade causa um padrão. A discussão final trata fatores socioeconômicos, educacionais e socioculturais como [[possíveis influências que exigem pesquisas contextualizadas adicionais]].', [2, 8], intro.concat(discussion));

add('Que lição metodológica o caso japonês de Linguistic Dead Ends trouxe para a adaptação brasileira, além de acrescentar um nome à lista de categorias?',
'O estudo japonês é apresentado como identificação de manipulação da linguagem que dificulta ou impede a compreensão da interface e do conteúdo. No protocolo brasileiro, a macroclasse [[Linguistic Dead-Ends]] e sua subclasse [[Untranslation]] foram incorporadas porque apareceram na fase de teste. Assim, a adaptação não foi uma expansão arbitrária do catálogo: articulou uma observação no piloto a uma categoria já descrita em pesquisa anterior. Essa decisão mostra a importância de permitir que o corpus confronte o instrumento de classificação. Ela não implica que todo conteúdo estrangeiro seja automaticamente enganoso nem que a classe tenha sido inventada pelo estudo brasileiro.', [1, 2, 3], intro.concat(adaptation));

add('Como as duas perguntas de investigação do Interact delimitam aquilo que o estudo consegue responder sobre padrões enganosos?',
'As perguntas concentram-se em [[frequência e tipos de DPs em aplicativos brasileiros populares]], organizados por classificações existentes, e em como esses resultados contrastam com pesquisas em outros cenários geográficos. A finalidade é estabelecer dados de base e um ponto de comparação com Estados Unidos e Japão. O desenho permite descrever ocorrências e discutir diferenças de distribuição e contexto. Não foi formulado como experimento de dano psicológico, teste de uma contramedida ou amostragem representativa de todo uso digital brasileiro. Compreender esse limite permite usar os achados como [[diagnóstico inicial]], sem convertê-los em estimativa universal de efeito sobre o bem-estar.', [2, 8], intro.concat(['5 Limitations']));

add('Ao passar de oito para nove categorias e de 240 para 100 aplicativos, quais adaptações de corpus o Interact declara em relação ao protocolo anterior?',
'O estudo acrescentou a categoria [[Tools]] às oito utilizadas por Di Geronimo e reduziu o corpus de 240 para [[100 aplicativos]]. A adaptação preserva a intenção de comparar presença e frequência de DPs, mas modifica o conjunto efetivamente observado. Essas mudanças devem acompanhar qualquer leitura comparativa, porque resultados agregados semelhantes não tornam os desenhos idênticos. O próprio artigo descreve o trabalho como uma classificação inicial de aplicativos em alta no contexto brasileiro. Na conclusão, pede ampliação do corpus e inclusão futura de Finance, explicitando que a seleção realizada não esgota categorias ou formas de uso possíveis.', [3, 8], adaptation.concat(['6 Conclusion']));

add('Como foi realizado o piloto que levou à escolha do emulador no Interact, e que justificativas foram apresentadas para essa escolha?',
'Duas duplas aplicaram gravação e classificação a [[nove aplicativos distintos]]: uma usou smartphones Android próprios e outra, um emulador. O emulador foi escolhido para manter [[consistência entre dispositivos e atender às limitações de orçamento]]. O teste indicou que padrões podiam ser detectados nas gravações de ambos os meios. Essa constatação sustentou uma decisão operacional, não uma equivalência universal entre emulação e uso real. A seção de limitações reconhece que certos padrões podem não aparecer em aplicativos emulados e que alguns apps bloquearam o emulador como suspeito. Assim, o piloto fundamenta o protocolo sem eliminar seus limites de observação.', [3, 8], adaptation.concat(['5 Limitations']));

add('Por que a inclusão da verificação dos termos e da política de privacidade e a regravação dos aplicativos do piloto importam para a rastreabilidade do protocolo?',
'O piloto levou à adição da tarefa de [[verificar termos de serviço e política de privacidade]], incorporando ao percurso de uso uma região em que barreiras informacionais poderiam ser observadas. Também ajudou a consolidar a consistência entre as duas duplas, que adotaram rotação de papéis. Os aplicativos usados no teste foram [[regravados por outro pesquisador para evitar viés]] e integraram a análise final. Esses procedimentos tornam explícito como decisões emergentes do teste passaram ao protocolo. Não demonstram eliminação de toda subjetividade ou viés; registram medidas adotadas para reduzir dependência de uma única gravação e de um único ponto de vista.', [3], adaptation);

add('O que a incorporação de Untranslation durante o piloto mostra sobre a relação entre um protocolo replicado e descobertas contextuais?',
'A pesquisa replica uma base anterior, mas informa que [[Linguistic Dead-Ends e Untranslation estavam presentes na fase de teste]] e, por isso, foram incluídas no processo brasileiro. Também identificou contextos específicos não relatados por Di Geronimo, posteriormente descritos como seis novos casos de aplicação de DPs conhecidos. A relação é de continuidade com adaptação: manter uma estrutura comparável não exige ignorar evidência que ela inicialmente não descrevia bem. Ao mesmo tempo, a presença desses casos não autoriza apresentar cada um como nova macroclasse. A contribuição contextual consiste em [[refinar a observação e a documentação]], preservando a distinção entre categoria e caso.', [3, 6], adaptation.concat(results));

add('Por que é necessário distinguir o levantamento inicial de 19 de janeiro da seleção final de 22 de janeiro de 2025 no corpus do Interact?',
'Em [[19 de janeiro de 2025]], os pesquisadores examinaram os cem aplicativos gerais em alta na Google Play brasileira, observando usos, avaliações suspeitas e categorias frequentes para aproximá-los do escopo anterior. A [[seleção final usou Sensor Tower em 22 de janeiro de 2025]], com quatro critérios de inclusão. Portanto, o panorama inicial e o corpus final são etapas relacionadas, mas não uma única lista automaticamente preservada. A descrição das datas e fontes é parte da rastreabilidade da amostragem: informa o recorte temporal e o processo de seleção, sem transformar rankings daquele momento em características estáveis do mercado atual.', [3], corpus);

add('Como a entrada de Tools e Finance no panorama inicial e a retirada de Finance revelam uma limitação material da seleção de aplicativos?',
'Tools e Finance não pertenciam às oito categorias originais e cada uma representava [[16 aplicativos entre os cem em alta]] no panorama inicial. Ambas foram acrescentadas ao escopo, mas Finance foi removida das etapas seguintes porque [[não funcionava nos emuladores]]. Isso mostra que a cobertura final dependeu não apenas de relevância de mercado, mas também da possibilidade técnica de observar os apps com o protocolo escolhido. A conclusão recomenda investigar Finance no futuro. Assim, a ausência dessa categoria não deve ser interpretada como ausência de padrões ou de riscos financeiros: ela marca um domínio que o corpus efetivamente analisado não cobriu.', [3, 8], corpus.concat(['6 Conclusion']));

add('Quais quatro condições de inclusão orientaram a seleção final e o que elas delimitam sobre a população observada?',
'Os aplicativos precisavam [[estar disponíveis para Android]], ser [[gratuitos para baixar]], estar em alta no Brasil e também em alta na respectiva categoria. Os quatro critérios delimitam uma seleção de apps de circulação destacada naquele contexto, não uma amostra de todos os serviços digitais ou de todos os modelos de acesso. Gratuidade para download também não significa ausência de ofertas, anúncios ou compras dentro do app: esses mecanismos foram procurados no percurso de uso. Ao interpretar a prevalência encontrada, deve-se conservar essa combinação de plataforma, acesso inicial, posição no ranking e categoria, bem como as exclusões e falhas de execução posteriores.', [3, 4], corpus);

add('Quais exclusões, além da indisponibilidade de download, restringiram o corpus e por que elas devem acompanhar a interpretação dos resultados?',
'Foram excluídos aplicativos [[indisponíveis no Brasil]], já incluídos em outra categoria, do tipo Launcher, que exigiam assinatura para acessar funções principais e aqueles vinculados à identificação do cidadão para serviços governamentais, além dos indisponíveis para download. A lista atravessa as páginas físicas 3 e 4 e deve ser lida por inteiro. Essas exclusões impedem tratar o corpus como retrato de qualquer experiência móvel brasileira. Em particular, serviços públicos e experiências cujo uso central depende de assinatura ficaram fora do recorte. O estudo descreve padrões dentro da seleção operacional adotada; não apresenta esses grupos ausentes como livres de problemas ou menos relevantes para pesquisas futuras.', [3, 4], corpus);

add('Como a intenção de selecionar doze aplicativos por categoria se transformou na distribuição final de cem aplicativos?',
'Foram aprovados inicialmente [[doze aplicativos em alta por categoria]], mas falhas no emulador reduziram o conjunto analisado. A distribuição final foi de doze em Family, Music & Audio, News & Magazines, Photography e Social; onze em Shopping e Tools; nove em Communication e Entertainment. A soma é cem. Essa diferença entre planejamento e execução precisa ser preservada ao comparar categorias: o corpus final não possui o mesmo tamanho em todas elas. O artigo informa o motivo operacional da redução e não oferece base para concluir que as categorias com menos apps teriam, por esse fato, menor presença de padrões ou experiências intrinsecamente mais seguras.', [4], corpus);

add('Que medidas de preparação de dispositivo e de conta ajudaram a padronizar a gravação, e quais interações continuaram dependentes de infraestrutura externa?',
'Os pesquisadores usaram [[BlueStacks 5 emulando um Samsung Galaxy S22 Ultra]], com captura de tela por ferramenta nativa de computadores Windows. Cada pesquisador criou uma nova conta Gmail. Também compraram um cartão SIM e o colocaram em um smartphone para validar o uso em aplicativos que exigiam número de telefone. A descrição mostra uma combinação de emulação, contas e autenticação externa, importante para tornar o percurso observável. Ela não significa que todos os apps aceitaram a configuração ou que a experiência foi idêntica à de qualquer usuário habitual: bloqueios e possíveis diferenças na aparição de DPs são explicitamente reconhecidos como limites do emulador.', [4, 8], corpus.concat(['5 Limitations']));

add('Quais oito tarefas estruturaram os dez primeiros minutos de uso, e por que a condição “quando disponíveis” importa?',
'O roteiro incluía [[criar conta e sair; fechar e reabrir o app; visitar a página de mercado; acessar configurações; verificar termos e política de privacidade; continuar a compra até o checkout; tentar selecionar nomes de produtos em comércio eletrônico; e usar o app para sua finalidade]]. As tarefas eram executadas quando disponíveis dentro dos dez primeiros minutos. Essa condição evita pressupor que todas as categorias possuíam o mesmo percurso ou que cada gravação cobriu todas as ações. O roteiro amplia a consistência da observação, mas não representa todas as jornadas possíveis, interações prolongadas ou funções que dependessem de condições ausentes naquele primeiro uso.', [4, 8], corpus.concat(['5 Limitations']));

add('Como a decisão de chegar ao checkout sem realizar compras limita as conclusões sobre a experiência de monetização?',
'Entre as tarefas havia [[continuar a compra até o checkout]], mas os pesquisadores afirmam expressamente que [[não compraram produtos ou serviços]]. Assim, foi possível observar apresentações de ofertas e etapas anteriores ao pagamento dentro do protocolo, sem analisar necessariamente o que ocorreria após uma transação efetiva. Essa fronteira deve acompanhar a interpretação de mecanismos comerciais: o estudo não mede perda financeira dos participantes, satisfação após uma compra ou todo o ciclo contratual de um serviço. Os achados permanecem uma classificação de escolhas de interface acessadas no recorte de uso, e a própria seção de limitações admite que desvios desse escopo podem gerar resultados novos ou diferentes.', [4, 8], corpus.concat(['5 Limitations']));

add('Que papel a análise individual, a discussão dos vídeos e o terceiro pesquisador desempenham diante de DP Blindness e da subjetividade da classificação?',
'O protocolo alternou gravação e análise entre duas duplas. Dentro da classificação, os vídeos eram vistos [[primeiro individualmente e depois discutidos em conjunto para mitigar DP Blindness]]. Quando a dupla não chegava a acordo, um terceiro pesquisador desempatava. O texto relata kappa ponderado de Cohen de 0,64 como indicador de concordância. A função metodológica dessas etapas é tornar decisões discutíveis e resolver divergências, não garantir objetividade absoluta ou confirmar efeitos no usuário. O uso adicional de um guia de quarenta casos responde à dificuldade de identificar padrões apenas por descrições abstratas, combinando exemplos e deliberação na produção dos registros.', [4], classification);

add('Como o artigo diferencia macroclasses, subclasses e casos, e por que essa estrutura exige cuidado ao ler números de frequência?',
'A classificação combina a expansão de Di Geronimo da taxonomia de Gray com os achados linguísticos de Hidaka. Usa [[seis macroclasses]], subdivisões e um guia de casos específicos. Alguns casos se ajustavam mais diretamente à própria macroclasse; por isso, Nagging, Obstruction e Forced Action também funcionam como subclasses em si mesmas. Isso significa que uma mesma palavra pode nomear níveis distintos da estrutura, e o percentual de uma macroclasse não precisa ser o de sua subclasse homônima. Os resultados separam explicitamente essas camadas. A lista taxonômica deve ser lida como descrita no documento, sem inventar definições completas das classes cuja explicação é remetida a outros trabalhos.', [4, 5], classification.concat(results));

add('Por que o guia de quarenta casos específicos é uma peça metodológica distinta da lista de categorias da taxonomia?',
'O artigo afirma que o guia de [[quarenta casos específicos de DPs]] foi usado para enfrentar a subjetividade de identificar padrões apenas com base nas descrições das categorias. A taxonomia fornece a organização conceitual; os casos aproximam essa organização de manifestações concretas. Além disso, a análise encontrou casos mais diretamente associados a macroclasses, levando ao uso de algumas delas como subclasses funcionais. Isso mostra que operacionalizar um catálogo envolve critérios e exemplos, não só nomes. O texto não fornece nesta página o conteúdo integral dos quarenta casos, portanto não seria válido completá-los por conhecimento externo ou tratá-los como quarenta ocorrências encontradas no corpus.', [4, 5], classification);

add('Por que a regra de não contar reaparições iniciais impede ler os 751 DPs como número bruto de todas as exposições durante o uso?',
'O protocolo registra que, para não deixar o próprio uso interferir na aparição de padrões, [[não foram contadas recorrências de DPs que já haviam aparecido no início do app]]. Os 751 registros devem ser entendidos dentro dessa convenção de classificação e observação, não como toda exposição repetida possível na experiência cotidiana. A contagem também está limitada à janela inicial e às tarefas realizadas. Por isso, não é adequado converter diretamente o total em intensidade de exposição prolongada ou carga acumulada de dano. A regra é parte da unidade de análise e precisa acompanhar comparações com outros protocolos que possam contabilizar repetições de modo diferente.', [4, 5, 8], classification.concat(results, ['5 Limitations']));

add('O que a distribuição em faixas de zero a dois, três a seis e pelo menos sete padrões acrescenta à média de 7,51 no corpus?',
'As faixas mostram [[13 aplicativos com zero a dois DPs, 41 com três a seis e 46 com pelo menos sete]]. A média de 7,51 e o desvio-padrão relatado de 4,7 sintetizam a contagem, mas não substituem a distribuição entre apps. A prevalência de 96% indica presença de ao menos um padrão; as faixas descrevem concentração e diversidade de quantidades dentro do corpus. Assim, presença, média e distribuição respondem a perguntas diferentes. Nenhuma dessas medidas, isoladamente, quantifica gravidade psicológica, frequência diária de uso ou dano experimentado por uma pessoa; elas são descrições das ocorrências classificadas no recorte analisado.', [5], results);

add('Como interpretar a média de 3,7 macroclasses por app em conjunto com a média de 4,4 subclasses, sem confundir diversidade de tipos com total de ocorrências?',
'O artigo informa média de [[3,7 macroclasses por aplicativo]], com desvio-padrão 1,5, e de [[4,4 subclasses por aplicativo]]. Essas medidas descrevem quantos tipos ou níveis classificatórios estavam presentes, enquanto a média de 7,51 diz respeito à quantidade de DPs contabilizados. Um aplicativo pode apresentar vários casos dentro da mesma classe, de modo que diversidade taxonômica e número de ocorrências não são sinônimos. A distinção também evita somar percentuais de classes como se fossem grupos mutuamente exclusivos de usuários: um mesmo app pode conter várias delas. Todos os valores permanecem vinculados ao corpus e ao protocolo, não a uma escala validada de dano.', [5], results);

add('Por que é incorreto igualar o percentual de apps com Nagging ao total de ocorrências de Nagging, ou confundir Forced Action macroclasse com subclasse?',
'Nagging aparece em [[78% dos apps]], mas totaliza [[201 ocorrências]] na classificação. Forced Action é descrita em 62% como macroclasse e em 54% como subclasse homônima; o total de ocorrências dessa subclasse é 115. O artigo também registra 75 aparições de Disguised Ad. Percentuais de aplicativos indicam presença, enquanto totais de casos contam ocorrências conforme o protocolo. A camada taxonômica deve acompanhar o número para evitar comparações inválidas. Esses resultados não medem quantas pessoas foram afetadas nem a gravidade de cada mecanismo, e não exigem reproduzir a comparação inferencial ambígua apresentada na página seguinte.', [5], results);

add('O que o caso do aplicativo com 25 DPs e os quatro apps sem registros permite afirmar, e o que não permite?',
'No corpus, [[Notícias Globais teve 25 DPs distribuídos em sete subclasses]], e apenas quatro aplicativos não apresentaram casos; dois destes pertenciam a News and Magazine. Esses extremos mostram heterogeneidade entre apps, inclusive dentro de uma categoria. Não seria válido concluir, apenas daí, que toda a categoria de notícias é a pior ou a mais segura, nem que um app sem registro no protocolo é livre de padrões em qualquer jornada. A janela de dez minutos e as restrições de emulação podem deixar outras ocorrências fora de observação. O dado é um resultado descritivo localizado, não uma certificação universal de segurança ou comparação causal de categorias.', [5, 8], results.concat(['5 Limitations']));

add('Como Terms/Policy Out of Bounds produz uma barreira distinta da mera ausência de um link para os termos?',
'O caso é classificado como [[Obstruction]]: o usuário é redirecionado a uma página externa, geralmente web, para acessar termos de serviço ou política de privacidade. O texto relaciona esse deslocamento a [[estresse desnecessário e menor probabilidade de leitura]]. Portanto, não se trata de afirmar que os termos não existem: o problema descrito é o percurso de acesso e a fricção adicional imposta a informação importante. O estudo documenta esse mecanismo como uma nova aplicação de padrão conhecido, sem apresentar experimento individual que estime o efeito de cada redirecionamento sobre leitura, compreensão ou bem-estar de todos os usuários.', [6], results);

add('Qual é o mecanismo específico de Ads with Layers, e por que ele não deve ser reduzido à simples presença de publicidade?',
'Ads with Layers é descrito como um caso de [[Obstruction]] formado por [[cadeias de múltiplos subanúncios com atrasos temporais]], para estender a exposição dentro de um mesmo conteúdo e realizar mais de uma chamada de atenção no mesmo intervalo. O foco está na composição temporal e na cadeia que prolonga a exposição, não na existência de qualquer anúncio isolado. Essa descrição permite argumentar sobre o mecanismo observado sem presumir que toda publicidade é enganosa. O artigo contabiliza os casos encontrados no corpus, mas não transforma a classificação em medida causal de desgaste cognitivo ou em estimativa de duração de exposição para toda a população.', [6, 7], results);

add('O que diferencia Task-based Rewards da atividade principal que o usuário procurou realizar no aplicativo?',
'O caso de [[Forced Action]] apresenta uma [[missão além do fluxo principal]] que, ao ser concluída, recompensa o usuário com algum aspecto dos serviços do app. A diferença relevante é o desvio condicionado por recompensa em relação à finalidade ou ao percurso principal da interação. A discussão observa estratégias que envolvem tarefas benéficas ao desenvolvedor, como habilitar notificações ou avaliar o aplicativo. A classificação não implica que toda meta ou recompensa seja necessariamente enganosa: exige reconhecer como a missão é inserida e o que ela condiciona. O trabalho documenta manifestações de interface; não mede causalmente a perda de autonomia provocada por cada missão.', [6, 7], results.concat(discussion));

add('Como Ad-locked Rewards liga uma ação publicitária a benefícios do aplicativo e quais exemplos de recompensa o artigo apresenta?',
'Ad-locked Rewards é um caso de [[Forced Action]] no qual o usuário é [[obrigado a assistir a um anúncio para receber uma recompensa]], como moedas virtuais, aceleradores de tempo ou outros bônus. O mecanismo descrito é a relação condicional entre exposição publicitária e obtenção do benefício. Para uma arguição, importa explicar essa estrutura, em vez de apenas memorizar o nome. O resultado não permite afirmar que todo bônus ou monetização funciona da mesma maneira, que o mecanismo ocorre em todos os jogos, ou que seus efeitos psicológicos foram medidos neste estudo. A descrição e a contagem dizem respeito aos casos reconhecidos no corpus de apps analisado.', [6, 7], results);

add('Por que Evoke Emotions to Take Action é apresentado como um caso de Toying with Emotions, e que tipo de conclusão deve ser evitado?',
'O caso usa [[linguagem ou elementos visuais apelativos para persuadir o usuário a agir]], sendo descrito como aplicação de Toying with Emotions. A discussão menciona mensagens persuasivas que direcionam atividades úteis ao desenvolvedor. A contribuição é especificar como um padrão conhecido pode se manifestar em interfaces observadas no contexto brasileiro. Deve-se evitar converter essa classificação em afirmação de que o estudo mediu uma emoção, sua intensidade ou um dano clínico no usuário. Também não basta a existência de qualquer elemento emocional para reproduzir a análise: é preciso conservar a função persuasiva e a ação direcionada que caracterizam o caso descrito.', [6, 7], results.concat(discussion));

add('Como comparar Terms/Policy in Another Language e Terms/Policy Out of Bounds sem tratar barreiras linguísticas e de navegação como um único mecanismo?',
'No primeiro caso, informações cruciais estão em [[outro idioma mesmo quando o app está no idioma do usuário]], criando uma barreira de compreensão, classificada como Untranslation. No segundo, o acesso exige [[redirecionamento para uma página externa]], descrito como Obstruction por acrescentar fricção e reduzir a probabilidade de leitura. Os dois casos dizem respeito a termos ou políticas, mas operam por meios diferentes e podem exigir investigações distintas. A distinção ajuda a não confundir disponibilidade, localização e compreensão da informação. O artigo apresenta esses mecanismos como aplicações de padrões conhecidos, não como demonstração de que traduzir ou reposicionar um documento, por si só, elimina qualquer dano.', [6, 7], results.concat(discussion));

add('Como se distribuem as 158 ocorrências dos seis casos contextuais, e por que essa distribuição não equivale à criação de seis novas macroclasses?',
'Foram registradas [[45 ocorrências de Terms/Policy in Another Language, 26 de Terms/Policy Out of Bounds, 42 de Ads with Layers, 20 de Task-based Rewards, 14 de Ad-locked Rewards e 11 de Evoke Emotions to Take Action]]. Juntas, correspondem a 158 casos, aproximadamente 21% dos 751 DPs encontrados. A distribuição especifica quais aplicações tiveram mais registros no corpus, sem alterar o fato de que se encaixam em padrões conhecidos. Não se deve ler esses totais como seis grupos exclusivos de aplicativos ou como números de usuários lesados. As unidades são os casos classificados pelo protocolo, com seus limites de recorrência, duração e emulação.', [6, 7], results);

add('Por que médias e prevalências próximas entre os resultados brasileiros e americanos não encerram a análise comparativa?',
'A discussão aproxima a média brasileira de [[7,51 DPs por app]] da média de 7,4 relatada pelo estudo americano e a prevalência de 96% da de 95%. Em seguida, destaca que [[a distribuição entre subclasses diferencia os cenários]]. Assim, medidas agregadas próximas podem coexistir com mecanismos e barreiras distribuídos de modo diferente. A análise precisa conservar a composição dos tipos, as adaptações metodológicas e os contextos de observação. Essa leitura não depende dos percentuais comparativos problemáticos da página 7 nem autoriza atribuir as diferenças a uma causa nacional única; o próprio texto sugere fatores contextuais a investigar em pesquisas futuras.', [5, 7, 8], results.concat(discussion));

add('Como a discussão de fatores socioeconômicos, educacionais e socioculturais deve orientar hipóteses sem ser convertida em explicação causal já testada?',
'O artigo afirma que as diferenças entre contextos [[sugerem que fatores socioeconômicos, educacionais e socioculturais podem influenciar como, onde e quando os DPs se manifestam]]. Essa formulação é uma hipótese interpretativa e uma orientação de pesquisa, não um experimento que isolou o efeito de cada fator. A introdução destaca heterogeneidades brasileiras e a discussão ressalta Untranslation como problema relevante. Para correlacionar esses pontos, deve-se manter o verbo de possibilidade e o recorte do corpus. Não é adequado concluir que uma condição educacional produz necessariamente um padrão ou que todos os usuários do país terão a mesma experiência de compreensão e resistência.', [2, 7, 8], intro.concat(discussion));

add('Por que investigar Finance, ampliar o corpus e incluir mais contextos do Sul Global são continuação necessária do diagnóstico, e não etapas já concluídas?',
'A conclusão propõe [[estudar padrões em aplicativos Finance]], ampliar o corpus e incluir mais representantes do Sul Global e suas particularidades. Finance foi retirada porque não funcionava no emulador, e o estudo analisou apps gratuitos em alta durante dez minutos de primeiro uso. Essas condições tornam os próximos passos substantivos: ampliariam domínios e experiências que o diagnóstico atual não observa. O convite a estudar economia, bem-estar e cultura também aponta questões de impacto ainda abertas. Não é correto apresentar essas recomendações como resultados de uma investigação financeira ou longitudinal já realizada, nem afirmar que ampliar apenas o tamanho da amostra resolveria todas as limitações contextuais.', [3, 8], corpus.concat(['5 Limitations', '6 Conclusion']));

add('Como Untranslation e Terms/Policy Out of Bounds podem ser usados para discutir o princípio 3.2 de Safety by Design sem confundir informação disponível com informação compreensível?',
'Como [[síntese analítica]], os casos do Interact mostram duas barreiras diferentes: o idioma dificulta compreender informações cruciais, enquanto o deslocamento para uma página externa adiciona fricção ao acesso. O princípio 3.2 de SbD recomenda políticas visíveis, fáceis de localizar, atualizadas e compreensíveis, com linguagem simples e comunicação adequada a usuários jovens. A relação permite perguntar não apenas se há termos publicados, mas [[se a pessoa consegue encontrá-los e entendê-los no contexto de uso]]. Isso não demonstra que o princípio foi testado nos apps ou que traduzir um texto elimina danos. As notas SbD são ilustrações de 2019, e o Interact não mede causalmente compreensão ou bem-estar.', [6, 7], results.concat(discussion), [['sbd', [21, 34, 35], ['Principle 3.2']]]);

add('Que diferença existe entre auditar dez minutos de uso de um app e executar a avaliação documentada de risco recomendada pelo princípio 1.6 de Safety by Design?',
'A auditoria do Interact documenta [[padrões observados em uma janela inicial, sob tarefas e condições de emulação]]. O princípio 1.6 de SbD recomenda avaliação documentada de risco e impacto, remediação de danos potenciais e adaptação dos fluxos conforme o uso e os riscos mudam; a nota LEGO ilustra exame de novas funções antes da entrada no mercado. A conexão é entre diagnóstico e processo de prevenção contínua, não equivalência de procedimentos. Uma auditoria pode informar perguntas para gestão de risco, mas não constitui por si só esse sistema, nem comprova eficácia preventiva. Também não se deve afirmar que os autores do Interact executaram avaliações pré-lançamento das empresas estudadas.', [3, 4, 8], adaptation.concat(corpus, ['5 Limitations']), [['sbd', [21, 27], ['Principle 1.6']]]);

add('Por que a prevalência de padrões no Interact não substitui as métricas de eficácia e responsabilização discutidas no princípio 3.4 de Safety by Design?',
'O Interact descreve [[presença, distribuição e quantidade de casos]] em cem apps; não acompanha a redução de dano após uma política ou moderação. SbD 3.4 propõe publicação de análises significativas sobre abusos, esforços de moderação e cumprimento das regras, distinguindo escala de denúncias da avaliação de eficácia. A correlação ajuda a separar uma linha de base descritiva da pergunta sobre [[o que uma medida preventiva realmente muda]]. Nem a prevalência observada prova falha causal de uma prática específica, nem a publicação de um relatório prova proteção. As notas SbD são ilustrativas, e os dois documentos exigem cuidado para que números de atividade não sejam tratados automaticamente como resultados de bem-estar.', [5, 8], results.concat(['5 Limitations']), [['sbd', [21, 36], ['Principle 3.4']]]);

add('Como o caso de termos em outro idioma se relaciona ao §12 do Art. 48 local, preservando o alcance específico da disposição?',
'O Interact descreve termos ou política de privacidade em outro idioma, apesar de o app estar no idioma do usuário, como barreira informacional. No documento local do Art. 48, o §12 se refere aos [[termos de uso dos fornecedores de serviços digitais que hospedem conteúdo de terceiros]] e à informação clara e acessível sobre a indicação etária atribuída pelo órgão competente ou, na ausência, pelo modelo autorizado. A comparação permite discutir como a barreira de idioma pode tensionar acesso à informação. Não transforma o §12 em exigência genérica de traduzir qualquer documento de todo aplicativo, nem prova infração jurídica de um app analisado. Não se verifica vigência normativa aqui.', [6, 7], results.concat(discussion), [['art', [4], ['Art. 48, §12']]]);

add('Ao correlacionar Ads with Layers e Ad-locked Rewards com funcionalidades do §10 do Art. 48, por que é preciso distinguir mecanismo de interface de critério classificatório?',
'No Interact, Ads with Layers prolonga exposição por cadeias de subanúncios e Ad-locked Rewards condiciona benefícios à visualização publicitária. O Art. 48 local considera funcionalidades e conteúdos na atribuição da classificação, incluindo interação que favoreça compulsividade e exemplos de [[manutenção do usuário ativo por períodos prolongados]], como recompensas variáveis, notificações e gamificação. A ponte é analítica: mecanismos concretos ajudam a formular perguntas sobre condições de uso. Não significa que toda publicidade, recompensa ou gamificação seja um dark pattern, nem que um critério classificatório meça o dano causado por ele. O estudo de apps tampouco demonstra a eficácia ou a aplicação jurídica da classificação.', [6, 7], results, [['art', [3, 4], ['Art. 48, §10']]]);

add('Como as barreiras observadas em políticas e termos podem dialogar com controles parentais e moderação considerados pelo Art. 48, sem equiparar classificação a segurança?',
'O Interact identifica fricções de acesso e compreensão em informações relevantes ao usuário. O documento local do Art. 48, nos §§14–15, considera [[controle editorial e curadoria, ferramentas de controle etário e parental acessíveis e políticas de moderação]], remetendo especificações aos Guias Práticos. A correlação permite discutir que um recurso listado precisa ser analisado no contexto em que a pessoa o encontra e compreende, e que a classificação envolve fatores além de um rótulo. Contudo, o Interact não testou a eficácia desses controles, e os parágrafos não demonstram que classificar um serviço elimina os padrões observados. Os Guias não fornecidos não podem ser preenchidos com conhecimento externo; não se afirma vigência do documento.', [6, 8], results.concat(['5 Limitations']), [['art', [4, 5], ['Art. 48, §§14–15']]]);

add('Como a barreira linguística de Untranslation e o creator-consumer divide podem ser articulados sem reduzir a vulnerabilidade a uma incapacidade individual?',
'O Interact observa [[informação crucial em idioma estrangeiro]] e discute desigualdades educacionais, letramento digital e acesso tecnológico como parte de um contexto heterogêneo. CHIP propõe o creator-consumer divide como lente para assimetrias estruturais entre onde jogos são criados e onde são consumidos, incluindo precariedade e exportação de perspectivas WEIRD. A síntese desloca a pergunta de uma suposta falha individual para [[condições de design, compreensão e poder]]. Isso não prova que o divide causou cada caso de Untranslation, nem transfere a prevalência dos cem apps para jogos ou todo o Sul Global. O argumento de CHIP é teórico e especulativo; o Interact oferece um diagnóstico observacional delimitado.', [2, 6, 8], intro.concat(results, ['5 Limitations']), [['chip', [1, 2], ['2 The Creator-Consumer Divide as a Lens for Understanding Systemic Player Vulnerability']]]);

add('Por que as consequências crônicas imaginadas no cenário de Helena não podem ser usadas como resultados de impacto do corpus de cem aplicativos do Interact?',
'O Interact gravou [[dez minutos de primeiro uso em emulador]] e classificou manifestações de interface; admite que uso prolongado pode revelar padrões diferentes. CHIP utiliza [[um cenário especulativo]] no qual Helena enfrenta ciclos de exploração financeira, criação de perfis e consequências cívicas. A comparação é útil para tornar visível a diferença entre documentar uma ocorrência e formular uma hipótese sobre sua trajetória sistêmica. Não há base para dizer que os apps auditados produziram os acontecimentos da ficção, ou que a contagem de padrões mede esses efeitos. A articulação sugere perguntas para investigações futuras de duração e contexto, preservando a distinção entre observação e provocação teórica.', [4, 8], corpus.concat(['5 Limitations']), [['chip', [2], ['3 A Speculative Perspective: Helena and The Gilded Cage of Ouroboros Seed']]]);

add('Como a proposta de ampliar a pesquisa no Sul Global pode dialogar com a exigência de parcerias equitativas de CHIP, além de aumentar o número de aplicativos?',
'A conclusão do Interact pede [[corpus maior, investigação de Finance e mais representantes do Sul Global]], reconhecendo fatores contextuais na manifestação dos padrões. CHIP questiona pesquisar contextos não WEIRD apenas como fontes de dados e propõe [[parcerias genuínas e equitativas para cocriar agendas e paradigmas de design]]. A síntese distingue expansão de cobertura de redistribuição de participação e poder na pesquisa. Uma pode contribuir para a outra, mas aumentar a quantidade de apps não demonstra, por si só, parceria equitativa nem elimina assimetrias de criação e consumo. Os documentos oferecem orientação de pesquisa e crítica teórica; não apresentam uma avaliação conjunta já realizada dessas estratégias.', [8], ['4 Discussions', '6 Conclusion'], [['chip', [2, 3], ['4 Toward a Decolonial Game and Play Research']]]);

add('Como o piloto, o guia de casos e a discussão entre classificadores do Interact ajudam a discutir a infraestrutura de conhecimento proposta na agenda de intervenção?',
'No Interact, o piloto alterou o protocolo, o guia de quarenta casos apoiou a identificação e a análise individual seguida de discussão e desempate tornou divergências tratáveis. A agenda de intervenção propõe [[léxico compartilhado, documentação contextual, revisão por pares, curadoria e versionamento]], junto de validação empírica de exemplos. A relação é de infraestrutura: exemplos e decisões rastreáveis ajudam a passar de nomes abstratos a práticas discutíveis e revisáveis. Não equivale a dizer que o protocolo de apps já construiu o repositório proposto para jogos ou validou alternativas éticas. Tampouco o acordo entre classificadores substitui avaliar como um padrão ou sua contramedida afeta autonomia e bem-estar.', [3, 4], adaptation.concat(classification), [['agenda', [7, 8], []]]);

add('Como Untranslation tensiona a ideia de que basta alertar o usuário para enfrentar padrões enganosos, à luz das ferramentas de agência propostas pela agenda?',
'Se informação crucial está em outro idioma ou é difícil de acessar, sua simples disponibilidade não garante uma escolha compreendida. A agenda propõe [[apoio contextual em tempo real]], com explicação de mecanismos e alternativas, mas exige preservar agência, evitar imposição de uma escolha supostamente melhor e considerar fadiga de alertas, falsos positivos e intrusão. A síntese permite perguntar que compreensão efetiva um alerta oferece diante de barreiras informacionais, sem transferir toda responsabilidade ao usuário. O Interact não testou esses instrumentos, e a agenda pede pesquisa empírica rigorosa para avaliá-los. Portanto, a combinação identifica um problema e requisitos de investigação, não uma solução de eficácia já demonstrada.', [6, 7, 8], results.concat(discussion, ['5 Limitations']), [['agenda', [9, 10], ['3.2 Development of Software Artifacts to Foster Real-Time Awareness on Users and Developers']]]);

add('Como distinguir uma missão externa condicionada por recompensa, descrita como Task-based Rewards, de uma tarefa de aprendizagem que oferece scaffolding em World Creation?',
'No Interact, [[Task-based Rewards apresenta uma missão além do fluxo principal]] cuja conclusão recompensa o usuário com algum aspecto do serviço. Em World Creation, Operationalizing discute outro papel para atividades e orientação: [[tutoriais, apresentação gradual de funcionalidades e feedback claro]] ajudam a tornar ferramentas criativas complexas aprendíveis e utilizáveis. A síntese exige examinar a função da tarefa: ela apoia o domínio da própria criação ou desloca o usuário para uma ação condicionada ao benefício? Não basta chamar a atividade de tutorial, nem pressupor que toda missão ou progressão seja enganosa. O texto também adverte que complexidade sem apoio pode dificultar competência; isso é diferente de impor uma tarefa externa como condição. A comparação articula descrições e critérios de design, sem afirmar que os estudos testaram conjuntamente essa distinção ou mediram efeitos causais sobre autonomia, competência e bem-estar.', [6, 7], results, [['op', [12, 13], ['Insufficient Scaffolding of Sophisticated Tools', 'Intuitive Design and Clear Feedback']]]);

add('Por que uma auditoria de casos enganosos e o campo Watch For de World Creation são complementares, mas não intercambiáveis, ao discutir bem-estar?',
'A auditoria do Interact descreve [[mecanismos reconhecidos nas interfaces de um corpus delimitado]], como barreiras linguísticas, anúncios em camadas e recompensas condicionadas. O campo Watch For de World Creation explicita riscos na implementação: bloquear ferramentas centrais por pagamento ou grind, obscurecer ferramentas, restringir compartilhamento e omitir apoio à aprendizagem. A ponte mostra duas tarefas distintas: detectar manifestações problemáticas e especificar condições preventivas de uma solução contextual. Não se pode concluir que ausência dos casos auditados torna qualquer jogo radiante, nem que uma ocorrência em app determina automaticamente frustração psicológica em outro contexto. A prevenção conceitual ainda demanda avaliação de experiências, perfis e resultados concretos.', [6, 8], results.concat(['5 Limitations']), [['op', [11, 12, 13], ['World Creation', 'Watch For']]]);

add('Como comparar classificação dialogada de DPs no Interact e governança de candidatos Radiant Patterns sem confundir acordo, recorrência e eficácia?',
'No Interact, o guia de casos, a classificação individual, a discussão em dupla e o desempate apoiam [[consistência das decisões de identificação]]. No framework HCI, o catálogo distingue candidatos e padrões finalizados, propõe verificação por especialistas, confronto com invariantes e refinamento iterativo. Ambos valorizam documentação e crítica, mas seus objetos e critérios diferem: classificar um problema observado não é verificar uma solução preventiva. Além disso, [[concordância ou maturidade documental não equivalem a efeito longitudinal demonstrado]]. O Interact tem limites de duração e emulação; o HCI reconhece amostra pequena centrada em especialistas e ausência de dados longitudinais. A articulação ajuda a explicar o valor e o limite de cada camada de evidência.', [4, 8], classification.concat(['5 Limitations']), [['hci', [13, 16], ['5 A Catalog of Games Radiant Patterns', '7 Final Remarks']]]);

add('Como articular adaptação contextual do protocolo Interact, invariantes e variantes do framework HCI e participação aberta em Safety by Design?',
'O Interact ajusta um protocolo anterior ao observar categorias, condições técnicas e casos linguísticos do contexto brasileiro. O framework HCI combina [[invariantes que preservam a identidade do padrão com variantes contextuais]], sem tratar uma descrição única como adequada a todo gênero ou perfil. SbD 3.3 recomenda [[engajamento aberto com usuários, especialistas independentes e partes interessadas]], porque consequências imprevistas podem escapar à equipe. A síntese propõe distinguir o que precisa permanecer rastreável, o que deve se adaptar e quem participa dessa decisão. Não afirma que os três trabalhos validaram conjuntamente um método universal. Auditoria curta, refinamento por especialistas e exemplos de boas práticas permanecem camadas limitadas, que exigem avaliação situada de resultados.', [3, 8], adaptation.concat(['4 Discussions', '5 Limitations']), [['hci', [10, 11, 16], ['Defining Hierarchical Scaling and Contextual Variants for RPs', '7 Final Remarks']], ['sbd', [21, 35], ['Principle 3.3']]]);

if (cards.length !== 50) throw new Error(`Expected 50, got ${cards.length}`);
const published = JSON.parse(fs.readFileSync(path.join(root, 'src/data/cards.json'), 'utf8').replace(/^\uFEFF/, ''));
const known = new Set(published.map(card => card.id));
for (const card of cards) {
  if (known.has(card.id)) throw new Error(`Existing id ${card.id}`);
  for (const { articleId, source: reference } of [{ articleId: card.articleId, source: card.source }, ...(card.relatedSources ?? [])]) {
    const document = documents.get(articleId);
    const originalHash = createHash('sha256').update(fs.readFileSync(path.join(root, 'artigos', reference.file))).digest('hex');
    if (originalHash !== document.sha256 || reference.title !== document.title) throw new Error(`Stale source ${articleId}`);
    for (const evidence of reference.evidence) if (!reference.pages.some(page => document.pages.find(item => item.page === page).text.includes(evidence))) throw new Error(`Missing evidence ${card.id}`);
  }
  const unmarked = card.answer.replace(/\[\[[^\[\]]+\]\]/g, '');
  if (unmarked.includes('[[') || unmarked.includes(']]')) throw new Error(`Unbalanced marker ${card.id}`);
}
fs.writeFileSync(path.join(out, `${primary}.json`), JSON.stringify(cards, null, 2) + '\n', 'utf8');
console.log(`${cards.length} candidates, ${cards.filter(card => card.kind === 'direct').length} direct, ${cards.filter(card => card.kind === 'synthesis').length} synthesis; source hashes, titles, evidence and markers checked. Not approved or published.`);
